        plan=PlanCuenta.objects.create(empresa=self.empresa,codigo="P2P",nombre="Plan P2P",creado_por=self.user);debit=CuentaContable.objects.create(empresa=self.empresa,plan=plan,codigo="1101",nombre="Inventario/Banco",tipo="ACTIVO",naturaleza="DEBITO",creado_por=self.user);credit=CuentaContable.objects.create(empresa=self.empresa,plan=plan,codigo="2101",nombre="Proveedor",tipo="PASIVO",naturaleza="CREDITO",creado_por=self.user);today=timezone.localdate();self.periodo=PeriodoContable.objects.create(empresa=self.empresa,anio=today.year,mes=today.month,fecha_inicio=today.replace(day=1),fecha_fin=(today.replace(day=28)+timedelta(days=4)).replace(day=1)-timedelta(days=1),creado_por=self.user);DiarioContable.objects.create(empresa=self.empresa,codigo="GENERAL",nombre="General",creado_por=self.user)
