    def test_e2e_transaccional_48_pasos(self):
        today=timezone.localdate();now=timezone.now();sol=SolicitudCompra.objects.create(empresa=self.empresa,numero="SC-E2E",titulo="Compra E2E",solicitante=self.user,centro_costo=self.cc,tipo_compra=self.tc,naturaleza="BIEN",fecha_solicitud=today,fecha_necesaria=today+timedelta(days=10),moneda=self.moneda,justificacion="Operación E2E",impacto_no_compra="Sin insumo",estado="APROBADA",total_estimado=100,creado_por=self.user);DetalleSolicitudCompra.objects.create(empresa=self.empresa,solicitud=sol,orden=1,tipo_linea="PRODUCTO",producto=self.producto,descripcion="Materia",cantidad=10,unidad_medida=self.um,precio_unitario_estimado=10,subtotal=100,total=100)
        exp=crear_expediente_desde_solicitud(context=self.ctx,solicitud_id=sol.pk);abrir_expediente(context=self.ctx,expediente_id=exp.pk);rfq=crear_rfq(context=self.ctx,expediente_id=exp.pk,datos={"titulo":"RFQ E2E","objeto":"Comprar materia","descripcion":"Proceso E2E","fecha_inicio":now+timedelta(hours=1),"fecha_limite":now+timedelta(days=5),"entrega_requerida_desde":today+timedelta(days=6),"entrega_requerida_hasta":today+timedelta(days=9),"lugar_entrega":"Almacén","almacen_destino":self.almacen,"condiciones_comerciales":"Crédito"});line=DetalleRFQ.objects.create(empresa=self.empresa,rfq=rfq,orden=1,tipo_linea="PRODUCTO",producto=self.producto,descripcion="Materia",cantidad=10,unidad_medida=self.um,fecha_entrega_requerida=today+timedelta(days=7),almacen_destino=self.almacen);agregar_proveedor_a_rfq(context=self.ctx,rfq_id=rfq.pk,proveedor_id=self.proveedor.pk,contacto_id=self.contacto.pk)
        offer=crear_oferta(context=self.ctx,rfq_id=rfq.pk,proveedor_id=self.proveedor.pk,datos={"valida_hasta":today+timedelta(days=20)});guardar_linea_oferta(context=self.ctx,oferta_id=offer.pk,linea_rfq_id=line.pk,datos={"cantidad":10,"precio_unitario":10,"impuesto":18});transicionar_oferta(context=self.ctx,oferta_id=offer.pk,nuevo="ENVIADA")
        comparison=crear_comparativo(context=self.ctx,rfq_id=rfq.pk);scenario=guardar_escenario(context=self.ctx,comparativo_id=comparison.pk,nombre="Balanceado",ponderaciones=comparison.ponderaciones);congelar_comparativo(context=self.ctx,comparativo_id=comparison.pk);award=crear_adjudicacion(context=self.ctx,comparativo_id=comparison.pk,tipo="TOTAL",selecciones=[{"oferta_id":offer.pk,"linea_rfq_id":line.pk,"cantidad":10}],justificacion="Recomendación determinista");aprobar_adjudicacion(context=self.ctx,adjudicacion_id=award.pk);order=crear_orden_desde_adjudicacion(context=self.ctx,adjudicacion_id=award.pk);transicionar_orden(context=self.ctx,orden_id=order.pk,nuevo="PENDIENTE_APROBACION");transicionar_orden(context=self.ctx,orden_id=order.pk,nuevo="APROBADA");transicionar_orden(context=self.ctx,orden_id=order.pk,nuevo="ENVIADA");transicionar_orden(context=self.ctx,orden_id=order.pk,nuevo="ACEPTADA")
        detail=order.detalles.get();ctx_r1=replace(self.ctx,clave_idempotente="e2e-recepcion-1");r1=crear_recepcion(context=ctx_r1,orden_id=order.pk,datos={"almacen":self.almacen});agregar_detalle_recepcion(context=ctx_r1,recepcion_id=r1.pk,detalle_orden_id=detail.pk,cantidad=4,lote="L-E2E",vence_el=today+timedelta(days=90));cerrar_recepcion(context=ctx_r1,recepcion_id=r1.pk);ctx_r2=replace(self.ctx,clave_idempotente="e2e-recepcion-2");r2=crear_recepcion(context=ctx_r2,orden_id=order.pk,datos={"almacen":self.almacen});agregar_detalle_recepcion(context=ctx_r2,recepcion_id=r2.pk,detalle_orden_id=detail.pk,cantidad=6,lote="L-E2E",vence_el=today+timedelta(days=90));cerrar_recepcion(context=ctx_r2,recepcion_id=r2.pk);self.producto.refresh_from_db();self.assertEqual(self.producto.stock_actual,10)
        invoice=crear_factura_proveedor(context=self.ctx,orden_id=order.pk,recepcion_id=r2.pk,datos={"numero":"FAC-E2E","vence_el":today+timedelta(days=30),"impuesto":18},lineas=[{"detalle_orden_id":detail.pk,"cantidad":10,"precio":10,"impuesto":18}]);account=validar_e_integrar_factura(context=self.ctx,factura_id=invoice.pk);note=crear_nota_credito(context=self.ctx,factura_id=invoice.pk,numero="NC-E2E",monto=18,motivo="Ajuste parcial");request=crear_solicitud_pago(context=self.ctx,cuenta_id=account.pk,monto=100);payment_order=aprobar_solicitud_y_orden(context=self.ctx,solicitud_id=request.pk);bank=CuentaBancariaEmpresa.objects.create(empresa=self.empresa,banco="Banco E2E",numero_enmascarado="****1234",moneda=self.moneda,saldo=1000);p1=pagar_orden(context=self.ctx,orden_id=payment_order.pk,cuenta_bancaria=bank,monto=40,referencia="PAGO-1");p2=pagar_orden(context=self.ctx,orden_id=payment_order.pk,cuenta_bancaria=bank,monto=60,referencia="PAGO-2");again=pagar_orden(context=self.ctx,orden_id=payment_order.pk,cuenta_bancaria=bank,monto=60,referencia="PAGO-2");self.assertEqual(p2.pk,again.pk)
        reconciliation=conciliar_movimiento(context=self.ctx,movimiento_id=p2.pk,desde=today.replace(day=1),hasta=today,saldo_banco=900);desconciliar_movimiento(context=self.ctx,movimiento_id=p2.pk,motivo="Validación E2E");self.assertTrue(balanza(empresa=self.empresa,periodo=self.periodo));self.assertGreaterEqual(AsientoContable.objects.filter(empresa=self.empresa).count(),5);self.assertTrue(EventoDominio.objects.filter(empresa=self.empresa).exists());self.assertTrue(EventoAuditoria.objects.filter(empresa=self.empresa).exists());self.assertTrue(RegistroIdempotencia.objects.filter(empresa=self.empresa).exists())
        with self.assertRaises(ValidationError):pagar_orden(context=self.ctx,orden_id=payment_order.pk,cuenta_bancaria=bank,monto=9999,referencia="ERROR")
        account.refresh_from_db();self.assertEqual(account.saldo,0);self.assertEqual(MovimientoTesoreria.objects.filter(empresa=self.empresa,tipo="EGRESO").count(),2);self.assertEqual(note.pk,NotaCreditoProveedor.objects.get(numero="NC-E2E").pk);self.assertEqual(scenario.comparativo_id,comparison.pk);self.assertEqual(reconciliation.cuenta_id,bank.pk)

    def test_http_post_csrf_idor_and_exports(self):
        self.client.force_login(self.user);self.assertEqual(self.client.get(reverse("compras:p2p_exportacion")).status_code,405);csrf=Client(enforce_csrf_checks=True);csrf.force_login(self.user);self.assertEqual(csrf.post(reverse("compras:p2p_exportacion"),{"recurso":"proveedores","formato":"csv"}).status_code,403)
        self.client.get(reverse("compras:p2p_dashboard"))
