    def test_wizard_persistente_reanudable_seguro_e_idempotente(self):
        sesion=iniciar(context=self.ctx,tipo="COMPRA",clave_idempotencia="wiz-1");misma=iniciar(context=self.ctx,tipo="COMPRA",clave_idempotencia="wiz-1");self.assertEqual(sesion.pk,misma.pk)
        guardar_paso(context=self.ctx,sesion_id=sesion.pk,numero=1,datos={"solicitud_id":123});reanudada=reanudar(context=self.ctx,sesion_id=sesion.pk);self.assertEqual(reanudada.paso_actual,2);self.assertEqual(reanudada.pasos.count(),11)
        with self.assertRaises(ValidationError):guardar_paso(context=self.ctx,sesion_id=sesion.pk,numero=4,datos={"salto":True})
        with self.assertRaises(ValidationError):guardar_paso(context=self.ctx,sesion_id=sesion.pk,numero=2,datos={"token":"secreto"})

    def test_wizard_expiracion_y_cross_tenant(self):
        sesion=iniciar(context=self.ctx,tipo="RECEPCION",clave_idempotencia="wiz-exp");WizardSession.objects.filter(pk=sesion.pk).update(expira_en=timezone.now()-timedelta(seconds=1));self.assertEqual(reanudar(context=self.ctx,sesion_id=sesion.pk).estado,"EXPIRADO")
        other_user=get_user_model().objects.create_user("wizard-other");other=Empresa.objects.create(usuario=other_user,nombre="Wizard otra",modulo_compras=True);other_ctx=OperationContext(empresa=other,usuario=other_user,clave_idempotente="other")
